<template>
  <PageTitle title="Daily Review" size="sm" />

  <div class="flex flex-col gap-6">
    <DailyReviewDateNav
      :date="date"
      :today-date="todayDate"
      :pending-dates="pendingDates"
      :min-date="minDate"
      :max-date="maxDate"
      @update:date="setDate"
    />

    <AppLoader v-if="isLoading" variant="inline" subject="daily review" />
    <AppError
      v-else-if="error"
      title="Failed to load daily review"
      :error="error"
      :action="refetch"
      action-text="Retry"
    />
    <template v-else-if="data">
      <DailyReviewProgress :shifts="data.shifts" />
      <DailyReviewDayStats :day-stats="data.day_stats" :previous-day-stats="data.previous_day_stats" />
      <DailyReviewFlagSummary v-model:active-filter="activeFilter" :shifts="data.shifts" />
      <DailyReviewShiftTable v-model:active-filter="activeFilter" :shifts="data.shifts" :date="date" />
    </template>
  </div>
</template>

<script setup lang="ts">
import type { FraudFlagType, ProjectShortInfo } from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

definePageMeta({
  backGroup: 'project-details',
  backLabel: 'project',
});

interface Props {
  projectId: string;
  projectShortInfo?: ProjectShortInfo;
}

const props = defineProps<Props>();

const route = useRoute();
const router = useRouter();
const { timezone } = useUserRole();

const todayDate = computed(() => formatDateTzToFormat(new Date().toISOString(), 'yyyy-MM-dd', timezone.value));

// Reviewable range: project start .. min(today, project end). Dates are yyyy-MM-dd
// strings, so lexicographic comparison is safe.
const minDate = computed(() => props.projectShortInfo?.start_date ?? null);
const maxDate = computed(() => {
  const end = props.projectShortInfo?.end_date;
  return end && end < todayDate.value ? end : todayDate.value;
});
const date = computed(() => {
  const raw = route.query.date;
  // Fallback is the last selectable day (today, or the project end for ended projects).
  return typeof raw === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(raw) ? raw : maxDate.value;
});

function setDate(value: string) {
  router.replace({ query: { ...route.query, date: value } });
}

const activeFilter = ref<FraudFlagType | null>(null);
watch(date, () => (activeFilter.value = null));

const projectIdRef = computed(() => props.projectId);
const { data, isLoading, error, refetch } = useProjectDailyReviewQuery(projectIdRef, date);
const { data: pendingDatesData } = useProjectDailyReviewPendingDatesQuery(projectIdRef);
const pendingDates = computed(() => pendingDatesData.value?.dates ?? []);
</script>
