<template>
  <section class="flex flex-col gap-2">
    <div class="flex flex-wrap items-center justify-between gap-2">
      <h2 class="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Work Shifts</h2>
      <div class="flex flex-wrap items-center gap-2">
        <button
          v-if="activeFilter"
          type="button"
          class="inline-flex cursor-pointer items-center gap-1 rounded-md px-2 py-0.5 text-xs font-medium"
          :class="[getDailyFlag(activeFilter).accentText, getDailyFlag(activeFilter).accentBg]"
          data-testid="daily-review-filter-chip"
          @click="emit('update:activeFilter', null)"
        >
          {{ getDailyFlag(activeFilter).label }} ✕
        </button>
        <span class="text-xs text-muted-foreground">Sort</span>
        <Select v-model="sortMode">
          <SelectTrigger class="h-8 w-44 text-xs"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem v-for="option in sortOptions" :key="option.key" :value="option.key" class="text-xs">{{
              option.label
            }}</SelectItem>
          </SelectContent>
        </Select>
      </div>
    </div>

    <AppEmpty v-if="!visibleShifts.length" subject="work shifts" variant="table" />

    <div v-else class="overflow-hidden rounded-xl border-2 bg-card">
      <div
        class="grid grid-cols-[minmax(170px,1.5fr)_64px_52px_84px_72px_minmax(168px,1.1fr)_130px_16px] items-center gap-3 border-b bg-muted/40 px-4 py-2 text-[11px] font-medium uppercase tracking-wide text-muted-foreground"
      >
        <span>Canvasser</span>
        <span class="text-right">Hrs</span>
        <span class="text-right">Doors</span>
        <span class="text-right">Surveys</span>
        <span class="text-right">Pay</span>
        <span>Flags</span>
        <span>Status</span>
        <span />
      </div>

      <NuxtLink
        v-for="shift in visibleShifts"
        :key="shift.id"
        :to="{
          name: 'workshifts-id',
          params: { id: shift.id },
          query: { reviewDate: props.date, reviewSort: sortMode },
        }"
        class="grid grid-cols-[minmax(170px,1.5fr)_64px_52px_84px_72px_minmax(168px,1.1fr)_130px_16px] items-center gap-3 border-b px-4 py-2.5 text-sm transition-colors last:border-b-0 hover:bg-muted/50"
        :data-testid="`daily-review-shift-row-${shift.id}`"
      >
        <div class="flex min-w-0 items-center gap-2.5">
          <UserNameWithCompany :user="shift.canvasser" />
        </div>

        <span class="text-right tabular-nums">{{
          shift.net_hours != null ? formatHoursDuration(shift.net_hours) : '—'
        }}</span>
        <span class="text-right tabular-nums text-muted-foreground">{{ shift.doors ?? '—' }}</span>
        <span class="text-right tabular-nums text-muted-foreground">
          {{ shift.surveys ?? '—' }}
          <span v-if="surveyPct(shift) != null" class="text-xs">({{ surveyPct(shift) }}%)</span>
        </span>
        <span class="text-right tabular-nums text-muted-foreground">{{
          shift.pay != null ? `$${shift.pay.toFixed(0)}` : '—'
        }}</span>

        <div class="flex min-w-0 items-center gap-1">
          <component
            :is="getDailyFlag(key).icon"
            v-for="key in DAILY_FLAG_ORDER"
            :key="key"
            class="size-4 shrink-0"
            :class="shift.flag_types?.includes(key) ? getDailyFlag(key).accentText : 'text-gray-300'"
            :title="getDailyFlag(key).label"
          />
        </div>

        <Badge :variant="reviewBadge(shift).variant" size="sm" class="w-fit">{{ reviewBadge(shift).label }}</Badge>

        <ChevronRightIcon class="size-4 shrink-0 text-muted-foreground" />
      </NuxtLink>
    </div>
  </section>
</template>

<script setup lang="ts">
import { ChevronRightIcon } from 'lucide-vue-next';
import type { BadgeVariants } from '~/components/ui/badge';
import type { DailyReviewShift, FraudFlagType } from '~/client';
import { DAILY_FLAG_ORDER, getDailyFlag } from '~/constants/workshifts/dailyReviewConfig';
import { sortDailyReviewShifts, shiftSurveyPct, type DailyReviewSortKey } from '~/utils/dailyReview';

const props = defineProps<{ shifts: DailyReviewShift[]; activeFilter: FraudFlagType | null; date: string }>();
const emit = defineEmits<{ 'update:activeFilter': [value: FraudFlagType | null] }>();

const sortMode = ref<DailyReviewSortKey>('most-flags');
const sortOptions: { key: DailyReviewSortKey; label: string }[] = [
  { key: 'most-flags', label: 'Most flags' },
  { key: 'lowest-survey', label: 'Lowest survey %' },
  { key: 'canvasser', label: 'Canvasser name' },
];

const surveyPct = shiftSurveyPct;

const visibleShifts = computed(() => {
  const filtered = props.activeFilter
    ? props.shifts.filter((shift) => shift.flag_types?.includes(props.activeFilter as FraudFlagType))
    : props.shifts;
  return sortDailyReviewShifts(filtered, sortMode.value);
});

function reviewBadge(shift: DailyReviewShift): { label: string; variant: BadgeVariants } {
  if (!shift.is_reviewable) return { label: 'Ongoing', variant: 'default' };
  return shift.is_reviewed ? { label: 'Reviewed', variant: 'success' } : { label: 'Needs Review', variant: 'warning' };
}
</script>
