<template>
  <div class="flex flex-col gap-2">
    <Label class="text-xs text-muted-foreground">Review day</Label>
    <div class="flex flex-wrap items-center gap-1">
      <Button
        variant="outline"
        size="icon"
        aria-label="Previous day"
        :disabled="!canGoTo(previousDate)"
        data-testid="daily-review-prev-day"
        @click="shiftDate(-1)"
      >
        <ChevronLeftIcon class="size-4" />
      </Button>
      <div class="flex h-10 min-w-40 items-center justify-center rounded-md border px-3 text-sm font-medium">
        {{ date }}
      </div>
      <Button
        variant="outline"
        size="icon"
        aria-label="Next day"
        :disabled="!canGoTo(nextDate)"
        data-testid="daily-review-next-day"
        @click="shiftDate(1)"
      >
        <ChevronRightIcon class="size-4" />
      </Button>
      <Button
        :variant="date === todayDate ? 'default' : 'outline'"
        :disabled="!canGoTo(todayDate)"
        @click="emit('update:date', todayDate)"
        >Today</Button
      >
      <Button
        :variant="date === yesterdayDate ? 'default' : 'outline'"
        :disabled="!canGoTo(yesterdayDate)"
        @click="emit('update:date', yesterdayDate)"
        >Yesterday</Button
      >
    </div>
    <div
      v-if="otherPendingDates.length"
      class="flex flex-wrap items-center gap-1.5"
      data-testid="daily-review-pending-dates"
    >
      <span class="text-xs text-muted-foreground">Needs review:</span>
      <button
        v-for="pending in otherPendingDates"
        :key="pending"
        type="button"
        class="inline-flex items-center gap-1 rounded-md bg-amber-100 px-2 py-0.5 text-xs font-medium text-amber-800 transition-colors hover:bg-amber-200"
        @click="emit('update:date', pending)"
      >
        <FlagIcon class="size-3" /> {{ pending }}
      </button>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ChevronLeftIcon, ChevronRightIcon, FlagIcon } from 'lucide-vue-next';
import { addDays, format, parseISO } from 'date-fns';

const props = defineProps<{
  date: string;
  todayDate: string;
  pendingDates: string[];
  // Selectable range: [minDate, maxDate], both yyyy-MM-dd (lexicographic compare is
  // safe). minDate null = no lower bound; maxDate already caps at today (page-side).
  minDate: string | null;
  maxDate: string;
}>();
const emit = defineEmits<{ 'update:date': [value: string] }>();

const yesterdayDate = computed(() => format(addDays(parseISO(props.todayDate), -1), 'yyyy-MM-dd'));
const previousDate = computed(() => format(addDays(parseISO(props.date), -1), 'yyyy-MM-dd'));
const nextDate = computed(() => format(addDays(parseISO(props.date), 1), 'yyyy-MM-dd'));
// The currently viewed date's own indicator is redundant — the page already shows its progress.
const otherPendingDates = computed(() => props.pendingDates.filter((d) => d !== props.date));

function canGoTo(target: string): boolean {
  if (props.minDate && target < props.minDate) return false;
  return target <= props.maxDate;
}

function shiftDate(days: number) {
  const target = format(addDays(parseISO(props.date), days), 'yyyy-MM-dd');
  if (!canGoTo(target)) return;
  emit('update:date', target);
}
</script>
