<template>
  <Card class="overflow-hidden border-2">
    <div class="flex items-center justify-between gap-3 border-b bg-muted/40 px-4 py-3">
      <div class="flex items-center gap-2.5">
        <FlagIcon class="size-5 text-muted-foreground" />
        <div class="flex flex-col">
          <span class="text-sm font-semibold">Flag Summary</span>
          <span class="text-xs text-muted-foreground">Click a category to filter the work shifts below.</span>
        </div>
      </div>
      <div class="flex items-center gap-3">
        <span class="text-xs text-muted-foreground">total flags</span>
        <span class="w-8 text-right text-2xl font-bold tabular-nums">{{ totalFlags }}</span>
      </div>
    </div>

    <button
      v-for="row in rows"
      :key="row.key"
      type="button"
      class="flex w-full items-center gap-3 border-b px-4 py-2 text-left transition-colors last:border-b-0 hover:bg-muted/60"
      :class="[activeFilter === row.key ? 'bg-muted' : '', row.count ? '' : 'opacity-60']"
      :data-testid="`daily-review-flag-${row.key}`"
      @click="toggle(row.key)"
    >
      <div class="flex size-8 shrink-0 items-center justify-center rounded-md" :class="row.config.accentBg">
        <component :is="row.config.icon" class="size-4" :class="row.config.accentText" />
      </div>
      <div class="flex min-w-0 flex-1 items-baseline gap-2">
        <span class="shrink-0 text-sm font-semibold">{{ row.config.label }}</span>
        <span class="truncate text-xs text-muted-foreground">{{ row.config.description }}</span>
      </div>
      <span
        class="w-8 shrink-0 text-right text-lg font-bold tabular-nums"
        :class="row.count ? '' : 'text-muted-foreground'"
      >
        {{ row.count }}
      </span>
    </button>
  </Card>
</template>

<script setup lang="ts">
import { FlagIcon } from 'lucide-vue-next';
import type { DailyReviewShift, FraudFlagType } from '~/client';
import { getDailyFlag } from '~/constants/workshifts/dailyReviewConfig';
import { computeFlagSummary } from '~/utils/dailyReview';

const props = defineProps<{ shifts: DailyReviewShift[]; activeFilter: FraudFlagType | null }>();
const emit = defineEmits<{ 'update:activeFilter': [value: FraudFlagType | null] }>();

const rows = computed(() => computeFlagSummary(props.shifts).map((row) => ({ ...row, config: getDailyFlag(row.key) })));
const totalFlags = computed(() => rows.value.reduce((total, row) => total + row.count, 0));

function toggle(key: FraudFlagType) {
  emit('update:activeFilter', props.activeFilter === key ? null : key);
}
</script>
