<template>
  <Card class="border-2">
    <CardContent class="p-0">
      <div class="grid grid-cols-3 border-b">
        <div
          v-for="(stat, index) in countStats"
          :key="stat.label"
          class="flex flex-col items-center gap-0.5 py-4 text-center"
          :class="index > 0 ? 'border-l' : ''"
        >
          <span class="text-xs uppercase tracking-wide text-muted-foreground">{{ stat.label }}</span>
          <span class="text-2xl font-bold">{{ stat.value }}</span>
          <span v-if="stat.delta != null" class="text-xs font-medium" :class="deltaClass(stat.delta)">
            {{ formatDelta(stat.delta) }} <span class="text-muted-foreground">vs. prev. day</span>
          </span>
        </div>
      </div>
      <div class="grid grid-cols-2 sm:grid-cols-4">
        <div
          v-for="(stat, index) in rateStats"
          :key="stat.label"
          class="flex flex-col items-center gap-0.5 border-b py-4 text-center sm:border-b-0"
          :class="index > 0 ? 'sm:border-l' : ''"
        >
          <span class="text-xs uppercase tracking-wide text-muted-foreground">{{ stat.label }}</span>
          <span class="text-xl font-bold">{{ stat.value }}</span>
          <span v-if="stat.delta != null" class="text-xs font-medium" :class="deltaClass(stat.delta)">
            {{ formatDelta(stat.delta) }} <span class="text-muted-foreground">vs. prev. day</span>
          </span>
        </div>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { DailyReviewDayStats } from '~/client';
import { computeDelta, computeRates, formatDelta } from '~/utils/dailyReview';

const props = defineProps<{ dayStats: DailyReviewDayStats; previousDayStats: DailyReviewDayStats }>();

function deltaClass(delta: number): string {
  return delta > 0 ? 'text-green-700' : delta < 0 ? 'text-red-700' : 'text-muted-foreground';
}

const dash = '—';

const countStats = computed(() => [
  {
    label: 'Canvassers',
    value: String(props.dayStats.canvassers_count),
    delta: computeDelta(props.dayStats.canvassers_count, props.previousDayStats.canvassers_count),
  },
  {
    label: 'Doors',
    value: props.dayStats.doors?.toLocaleString() ?? dash,
    delta: computeDelta(props.dayStats.doors, props.previousDayStats.doors),
  },
  {
    label: 'Surveys',
    value: props.dayStats.surveys?.toLocaleString() ?? dash,
    delta: computeDelta(props.dayStats.surveys, props.previousDayStats.surveys),
  },
]);

const rateStats = computed(() => {
  const rates = computeRates(props.dayStats);
  const previous = computeRates(props.previousDayStats);
  return [
    {
      label: 'Survey %',
      value: rates.surveyPct != null ? `${rates.surveyPct}%` : dash,
      delta: computeDelta(rates.surveyPct, previous.surveyPct),
    },
    { label: 'DPH', value: rates.dph != null ? String(rates.dph) : dash, delta: computeDelta(rates.dph, previous.dph) },
    {
      label: 'Hours / canvasser',
      value: rates.hoursPerCanvasser != null ? formatHoursDuration(rates.hoursPerCanvasser) : dash,
      delta: null,
    },
    {
      label: 'Doors / canvasser',
      value: rates.doorsPerCanvasser != null ? String(rates.doorsPerCanvasser) : dash,
      delta: null,
    },
  ];
});
</script>
